function MinimumDeletions(s: string): integer;
begin
  var n := s.Length;
  var dp := new integer[n+1, n+1];

  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      if s[i+1] = s[n - j] then
        dp[i+1, j+1] := dp[i, j] + 1
      else
        dp[i+1, j+1] := Max(dp[i, j+1], dp[i+1, j]);

  Result := n - dp[n, n];
end;

