function SplitListIntoNParts(lst: array of integer; n: integer): List<List<integer>>;
begin
  var length := lst.Length;
  var partSize := length div n;
  var remainder := length mod n;
  Result := new List<List<integer>>;
  var start := 0;

  for var i := 0 to n - 1 do
  begin
    var endIndex := start + partSize + (if i < remainder then 1 else 0);
    var part := new List<integer>;
    for var j := start to endIndex - 1 do
      part.Add(lst[j]);
    Result.Add(part);
    start := endIndex;
  end;
end;

function CheckSubarray(nums: array of integer; k: integer): boolean;
begin
  var n := nums.Length;
  var prefixSum := new integer[n + 1];
  var remainderSet := new Dictionary<integer, integer>;
  remainderSet.Add(0, -1);

  for var i := 1 to n do
  begin
    prefixSum[i] := prefixSum[i - 1] + nums[i - 1];
    var remainder := prefixSum[i] mod k;

    if remainderSet.ContainsKey(remainder) then
    begin
      if i - remainderSet[remainder] > 1 then
      begin
        Result := True;
        exit;
      end;
    end
    else
      remainderSet.Add(remainder, i);
  end;

  Result := False;
end;

function SmallestSubWithGivenSum(arr: array of integer; targetSum: integer): integer;
begin
  var windowSum := 0;
  var minLength := integer.MaxValue;
  var windowStart := 0;

  for var windowEnd := 0 to arr.Length - 1 do
  begin
    windowSum += arr[windowEnd];

    while windowSum >= targetSum do
    begin
      minLength := Min(minLength, windowEnd - windowStart + 1);
      windowSum -= arr[windowStart];
      windowStart += 1;
    end;
  end;

  if minLength <> integer.MaxValue then
    Result := minLength
  else
    Result := 0;
end;

