function FindDeepestNode(root: TreeNode): integer;
begin
  if root = nil then
  begin
    Result := 0;
    exit;
  end;

  var queue := new Queue<TreeNode>;
  queue.Enqueue(root);
  var node := root;

  while queue.Count > 0 do
  begin
    node := queue.Dequeue;

    if node.left <> nil then
      queue.Enqueue(node.left);
    if node.right <> nil then
      queue.Enqueue(node.right);
  end;

  Result := node.val;
end;

