end;

function CalculateGameScore(ops: array of string): integer;
begin
  var ans := new List<integer>;
  var total := 0;

  foreach var item in ops do
  begin
    if item = '+' then
    begin
      var sumVal := ans[ans.Count-1] + ans[ans.Count-2];
      total += sumVal;
      ans.Add(sumVal);
    end
    else if item = 'C' then
    begin
      total -= ans[ans.Count-1];
      ans.RemoveAt(ans.Count-1);
    end
    else if item = 'D' then
    begin
      var doubleVal := ans[ans.Count-1] * 2;
      total += doubleVal;
      ans.Add(doubleVal);
    end
    else
    begin
      var num := StrToInt(item);
      ans.Add(num);
      total += num;
    end;
  end;

  Result := total;
end;

function LongestConsecutiveSequence(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var numSet := new HashSet<integer>(nums);
  var longestStreak := 0;

  foreach var num in numSet do
  begin
    if not numSet.Contains(num - 1) then
    begin
      var currentNum := num;
      var currentStreak := 1;

      while numSet.Contains(currentNum + 1) do
      begin
        currentNum += 1;
        currentStreak += 1;
      end;

      longestStreak := Max(longestStreak, currentStreak);
    end;
  end;

  Result := longestStreak;
end;

