function NoRepeatSubstr(s: string): integer;
begin
  var maxLength := 0;
  var startIndex := 0;
  var seenChars := new Dictionary<char, integer>;

  for var endIndex := 1 to s.Length do
  begin
    var ch := s[endIndex];
    if seenChars.ContainsKey(ch) and (startIndex <= seenChars[ch]) then
      startIndex := seenChars[ch] + 1
    else
      maxLength := Max(maxLength, endIndex - startIndex + 1);

    seenChars[ch] := endIndex;
  end;

  Result := maxLength;
end;

