function Decompress(s: string): string;
begin
  var stack := new Stack<object>;
  var currString := '';
  var currNum := 0;

  foreach var ch in s do
  begin
    if ch.IsDigit then
      currNum := currNum * 10 + StrToInt(ch)
    else if ch = '[' then
    begin
      stack.Push(currString);
      stack.Push(currNum);
      currString := '';
      currNum := 0;
    end
    else if ch = ']' then
    begin
      var num := integer(stack.Pop);
      var prevString := string(stack.Pop);
      currString := prevString + currString * num;
    end
    else
      currString += ch;
  end;

  Result := currString;
end;

function NextLargerNumber(n: integer): integer;
begin
  var numStr := n.ToString;
  var length := numStr.Length;
  var i := length - 2;

  while i >= 0 do
  begin
    if numStr[i+1] < numStr[i+2] then
      break;
    i -= 1;
  end;

  if i = -1 then
  begin
    Result := -1;
    exit;
  end;

  var j := length - 1;
  while j >= 0 do
  begin
    if numStr[j+1] > numStr[i+1] then
      break;
    j -= 1;
  end;

  var numList := numStr.ToCharArray.ToList;
  var temp := numList[i];
  numList[i] := numList[j];
  numList[j] := temp;

  var rest := numList.GetRange(i + 1, length - i - 1);
  rest.Sort;
  numList.RemoveRange(i + 1, length - i - 1);
  numList.AddRange(rest);

  Result := StrToInt(string.Join('', numList));
end;

function NumberComplement(num: integer): integer;
begin
  var mask := 1;
  while mask <= num do
    mask := mask shl 1;

  if mask > 0 then
    mask := mask - 1;

  Result := not num and mask;
end;

