function BalancedBinaryTrees(n: integer): integer;
begin
  if (n = 0) or (n = 1) then
    Result := 1
  else
  begin
    var C := new integer[n+1];
    C[0] := 1;
    C[1] := 1;

    for var i := 2 to n do
    begin
      C[i] := 0;
      for var j := 0 to i - 1 do
        C[i] := C[i] + C[j] * C[i-j-1];
    end;

    Result := C[n];
  end;
end;

function MaxSubarrays(nums: array of integer; k: integer): integer;
begin
  var n := nums.Length;
  var prefixSum := new integer[n + 1];
  for var i := 0 to n - 1 do
    prefixSum[i + 1] := prefixSum[i] + nums[i];

  var maxCount := 0;
  var start := 0;
  for var endIndex := 0 to n do
  begin
    while prefixSum[endIndex] - prefixSum[start] > k do
      start += 1;
    maxCount := Max(maxCount, endIndex - start);
  end;

  Result := maxCount;
end;

