      if letterCount.ContainsKey(lowerLetter) then
        letterCount[lowerLetter] += 1
      else
        letterCount.Add(lowerLetter, 1);
    end;

  var oddCount := 0;
  foreach var count in letterCount.Values do
    if count mod 2 <> 0 then
      oddCount += 1;

  Result := oddCount <= 1;
end;

