function CountPrimeNumbers(n: integer): integer;

  function IsPrime(num: integer): boolean;
  begin
    if num <= 1 then
      Result := False
    else if num = 2 then
      Result := True
    else if num mod 2 = 0 then
      Result := False
    else
    begin
      var i := 3;
      while i * i <= num do
      begin
        if num mod i = 0 then
        begin
          Result := False;
          exit;
        end;
        i += 2;
      end;
      Result := True;
    end;
  end;

begin
