function IsPossibleDivide(nums: array of integer; k: integer): boolean;
begin
  if nums.Length mod k <> 0 then
  begin
    Result := False;
    exit;
  end;

  var numCounts := new Dictionary<integer, integer>;
  foreach var num in nums do
    if numCounts.ContainsKey(num) then
      numCounts[num] += 1
    else
      numCounts.Add(num, 1);

  var sortedKeys := numCounts.Keys.ToList;
  sortedKeys.Sort;

  foreach var key in sortedKeys do
  begin
    if numCounts[key] > 0 then
    begin
      for var i := 1 to k - 1 do
      begin
        if (not numCounts.ContainsKey(key + i)) or (numCounts[key + i] < numCounts[key]) then
        begin
          Result := False;
          exit;
        end;
        numCounts[key + i] -= numCounts[key];
      end;
    end;
  end;

  Result := True;
end;

function MinGuessCost(n: integer): integer;
begin
  var pay := new integer[n+1, n+1];

  for var i := n - 1 downto 0 do
    for var j := i + 1 to n - 1 do
    begin
      var minVal := integer.MaxValue;
      for var k := i to j do
        minVal := Min(minVal, k + 1 + Max(pay[i, k-1], pay[k+1, j]));
      pay[i,j] := minVal;
    end;

  Result := pay[0, n-1];
end;

function GetUglyNumbers(n: integer): array of integer;
begin
  var ugly := new integer[n];
  ugly[0] := 1;
  var i2 := 0;
  var i3 := 0;
  var i5 := 0;
  var nextMultipleOf2 := 2;
  var nextMultipleOf3 := 3;
  var nextMultipleOf5 := 5;

  for var i := 1 to n - 1 do
  begin
    var nextUgly := Min(nextMultipleOf2, Min(nextMultipleOf3, nextMultipleOf5));
    ugly[i] := nextUgly;

    if nextUgly = nextMultipleOf2 then
    begin
      i2 += 1;
      nextMultipleOf2 := ugly[i2] * 2;
    end;

    if nextUgly = nextMultipleOf3 then
    begin
      i3 += 1;
      nextMultipleOf3 := ugly[i3] * 3;
    end;

    if nextUgly = nextMultipleOf5 then
    begin
      i5 += 1;
      nextMultipleOf5 := ugly[i5] * 5;
    end;
  end;

  Result := ugly;
end;

function SearchRotatedArray(nums: array of integer; target: integer): integer;

  function FindRotationPoint(arr: array of integer): integer;
  begin
    var low := 0;
    var high := arr.Length - 1;
    while low < high do
    begin
      var mid := low + (high - low) div 2;
      if arr[mid] > arr[high] then
        low := mid + 1
      else
        high := mid;
    end;
    Result := low;
  end;

  function BinarySearch(low, high: integer; targetVal: integer; arr: array of integer): integer;
  begin
    while low <= high do
    begin
      var mid := low + (high - low) div 2;
      if arr[mid] = targetVal then
      begin
        Result := mid;
        exit;
      end
      else if arr[mid] < targetVal then
        low := mid + 1
      else
        high := mid - 1;
    end;
    Result := -1;
  end;

begin
  var rotationPoint := FindRotationPoint(nums);

  if nums[rotationPoint] = target then
  begin
    Result := rotationPoint;
    exit;
  end;

  if nums[0] = target then
  begin
    Result := 0;
    exit;
  end;

  if rotationPoint = 0 then
    Result := BinarySearch(0, nums.Length - 1, target, nums)
  else if target < nums[0] then
    Result := BinarySearch(rotationPoint, nums.Length - 1, target, nums)
  else
    Result := BinarySearch(0, rotationPoint - 1, target, nums);
end;

