  var extendedHeight := new integer[height.Length + 2];
  extendedHeight[0] := 0;
  for var i := 0 to height.Length - 1 do
    extendedHeight[i + 1] := height[i];
  extendedHeight[extendedHeight.Length - 1] := 0;

  var leftMax := new integer[extendedHeight.Length];
  var rightMax := new integer[extendedHeight.Length];

  for var i := 1 to extendedHeight.Length - 1 do
    leftMax[i] := Max(extendedHeight[i], leftMax[i - 1]);

  for var i := extendedHeight.Length - 2 downto 0 do
    rightMax[i] := Max(extendedHeight[i], rightMax[i + 1]);

  var res := 0;
  for var i := 1 to extendedHeight.Length - 2 do
    res += Min(leftMax[i], rightMax[i]) - extendedHeight[i];

  Result := res;
end;

function CountDecodeWays(s: string): integer;
begin
  if (s.Length = 0) or (s[1] = '0') then
  begin
    Result := 0;
    exit;
  end;

  var n := s.Length;
  var dp := new integer[n + 1];
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
  begin
    if s[i] <> '0' then
      dp[i] := dp[i - 1];

    var twoDigit := StrToInt(s.Substring(i - 2, 2));
    if (s[i - 1] <> '0') and (twoDigit <= 26) then
      dp[i] += dp[i - 2];
  end;

  Result := dp[n];
end;

