function KnapSackSolution(values, weights: array of integer; capacity: integer): integer;
begin
  var dp := new integer[values.Length + 1, capacity + 1];

  for var i := 1 to values.Length do
    for var j := 0 to capacity do
      if weights[i - 1] > j then
        dp[i, j] := dp[i - 1, j]
      else
        dp[i, j] := Max(dp[i - 1, j], dp[i - 1, j - weights[i - 1]] + values[i - 1]);

  Result := dp[values.Length, capacity];
end;

