function FindMaxSumSubarray(arr: array of integer; k: integer): integer;
begin
  if (arr.Length = 0) or (k <= 0) or (k > arr.Length) then
  begin
    Result := 0;
    exit;
  end;

  var windowSum := 0;
  for var i := 0 to k - 1 do
    windowSum += arr[i];

  var maxSum := windowSum;

  for var i := 0 to arr.Length - k - 1 do
  begin
    windowSum := windowSum - arr[i] + arr[i + k];
    maxSum := Max(maxSum, windowSum);
  end;

  Result := maxSum;
end;

function FindSmallestSubarray(arr: array of integer; targetSum: integer): integer;
begin
  var windowSum := 0;
  var windowStart := 0;
  var minLength := integer.MaxValue;

  for var windowEnd := 0 to arr.Length - 1 do
  begin
    windowSum += arr[windowEnd];

    while windowSum >= targetSum do
    begin
      minLength := Min(minLength, windowEnd - windowStart + 1);
      windowSum -= arr[windowStart];
      windowStart += 1;
    end;
  end;

  if minLength <> integer.MaxValue then
    Result := minLength
  else
