function FindRepetition(A: array of integer; x: integer): integer;

  function FindFirstOccurrence(arr: array of integer; target: integer): integer;
  begin
    var left := 0;
    var right := arr.Length - 1;
    var resultIndex := -1;

    while left <= right do
    begin
      var mid := (left + right) div 2;
      if target = arr[mid] then
      begin
        resultIndex := mid;
        right := mid - 1;
      end
      else if target < arr[mid] then
        right := mid - 1
      else
        left := mid + 1;
    end;
    Result := resultIndex;
  end;

  function FindLastOccurrence(arr: array of integer; target: integer): integer;
  begin
    var left := 0;
    var right := arr.Length - 1;
    var resultIndex := -1;

    while left <= right do
    begin
      var mid := (left + right) div 2;
      if target = arr[mid] then
      begin
        resultIndex := mid;
        left := mid + 1;
      end
      else if target < arr[mid] then
        right := mid - 1
      else
        left := mid + 1;
    end;
    Result := resultIndex;
  end;

begin
  var first := FindFirstOccurrence(A, x);
  if first = -1 then
  begin
    Result := 0;
    exit;
  end;

  var last := FindLastOccurrence(A, x);
  Result := last - first + 1;
end;

