  for var right := 0 to n - 1 do
  begin
    if arr[right] = 0 then
    begin
      if zeroFound then
      begin
        while arr[left] <> 0 do
          left += 1;
        left += 1;
      end
      else
        zeroFound := True;
    end;

    maxLen := Max(maxLen, right - left);
  end;

  Result := maxLen;
end;

function MinDelPalindrome(s: string): integer;
