function MaxPairsSwap(arr: array of integer): integer;
begin
  var answer := 0;
  var elementCounts := new Dictionary<integer, integer>;

  foreach var num in arr do
    if elementCounts.ContainsKey(num) then
      elementCounts[num] += 1
    else
      elementCounts.Add(num, 1);

  foreach var star in elementCounts.Keys do
  begin
    if elementCounts[star] <= answer then
      continue;

    var cnt := 0;
    var idx := 0;
    while idx < arr.Length - 1 do
    begin
      if (arr[idx] = arr[idx + 1]) or ((arr[idx] <> star) and (arr[idx + 1] <> star)) then
      begin
        idx += 1;
        continue;
      end;

      cnt += 1;
      idx += 2;
    end;
    answer := Max(answer, cnt);
  end;

  if answer <> 0 then
    Result := answer
  else
    Result := 0;
end;

