function MaxCuboidVolume(L, W, H: integer): integer;
begin
  var sides := new integer[3];
  sides[0] := L;
  sides[1] := W;
  sides[2] := H;
  &Array.Sort(sides);

  var maxVolume := L * W * H;

  if (2 * H <= L) and (2 * H <= W) then
    maxVolume := Max(maxVolume, 4 * H * H * H);

  if 2 * W <= L then
    maxVolume := Max(maxVolume, W * W * (L - 2 * W));

  if 2 * L <= W then
    maxVolume := Max(maxVolume, L * L * (W - 2 * L));

  Result := maxVolume;
end;

function MinPathSteps(matrix: array [,] of integer; start, endPos: (integer, integer)): integer;
begin
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((start[0], start[1], 0));
  var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;

  var rows := matrix.GetLength(0);
  var cols := matrix.GetLength(1);
  var visited := new HashSet<(integer, integer)>;

  while queue.Count > 0 do
  begin
    var (x, y, steps) := queue.Dequeue;
    if (x = endPos[0]) and (y = endPos[1]) then
    begin
      Result := steps;
      exit;
    end;

    foreach var (dx, dy) in directions do
    begin
      var newX := x + dx;
      var newY := y + dy;
      if (newX >= 0) and (newX < rows) and (newY >= 0) and (newY < cols) and 
         (not visited.Contains((newX, newY))) and (matrix[newX, newY] = 0) then
      begin
        queue.Enqueue((newX, newY, steps + 1));
        visited.Add((newX, newY));
      end;
    end;
  end;

  Result := -1;
end;

function NextGreatestLetter(letters: array of char; target: char): char;
begin
  if letters.Length = 0 then
  begin
    Result := #0;
    exit;
  end;

  var low := 0;
  var high := letters.Length - 1;

  while low <= high do
  begin
    var mid := low + (high - low) div 2;
    if (mid > 0) and (letters[mid - 1] <= target) and (target < letters[mid]) then
    begin
      Result := letters[mid];
      exit;
    end
    else if letters[mid] <= target then
      low := mid + 1
    else
      high := mid - 1;
  end;

  Result := letters[0];
end;

