function FindTriplets(nums: array of integer): List<List<integer>>;
begin
  var triplets := new List<List<integer>>;
  var sortedNums := nums.ToList;
  sortedNums.Sort;
  var length := sortedNums.Count;

  for var i := 0 to length - 3 do
  begin
    if (i > 0) and (sortedNums[i] = sortedNums[i - 1]) then
      continue;

    var left := i + 1;
    var right := length - 1;

    while left < right do
    begin
      var total := sortedNums[i] + sortedNums[left] + sortedNums[right];
      if total < 0 then
        left += 1
      else if total > 0 then
        right -= 1
      else
      begin
        triplets.Add(new List<integer>([sortedNums[i], sortedNums[left], sortedNums[right]]));
        while (left < right) and (sortedNums[left] = sortedNums[left + 1]) do
          left += 1;
        while (left < right) and (sortedNums[right] = sortedNums[right - 1]) do
          right -= 1;
        left += 1;
        right -= 1;
      end;
    end;
  end;

  Result := triplets;
end;

