  var maxPalindrome := 0;

  for var i := maxNum downto minNum do
  begin
    for var j := i downto minNum do
    begin
      var product := i * j;
      if product <= maxPalindrome then
        break;

      var productStr := product.ToString;
      if productStr = ReverseString(productStr) then
        maxPalindrome := product;
    end;
  end;

  Result := maxPalindrome;
end;

