function LeastCommonDivisible(n: integer): integer;

  function GCD(a, b: integer): integer;
  begin
    while b <> 0 do
    begin
      var temp := b;
      b := a mod b;
      a := temp;
    end;
    Result := a;
  end;

  function LCM(a, b: integer): integer;
  begin
    Result := (a * b) div GCD(a, b);
  end;

begin
