function MaxSumSubarrays(A: array of integer; L, M: integer): integer;
begin
  var prefixSum := new integer[A.Length + 1];
  for var i := 0 to A.Length - 1 do
    prefixSum[i + 1] := prefixSum[i] + A[i];

  var res := prefixSum[L + M];
  var lMax := prefixSum[L];
  var mMax := prefixSum[M];

  for var i := 1 to A.Length - L - M do
  begin
    lMax := Max(lMax, prefixSum[L + i] - prefixSum[i]);
    mMax := Max(mMax, prefixSum[M + i] - prefixSum[i]);

    res := Max(res, 
      lMax + prefixSum[L + M + i] - prefixSum[L + i],
      mMax + prefixSum[L + M + i] - prefixSum[M + i]);
  end;

  Result := res;
end;

function CanDivide(nums: array of integer; k: integer): boolean;
begin
  var counts := new Dictionary<integer, integer>;
  foreach var num in nums do
    if counts.ContainsKey(num) then
      counts[num] += 1
    else
      counts.Add(num, 1);

  var sortedKeys := counts.Keys.ToList;
  sortedKeys.Sort;

  foreach var key in sortedKeys do
  begin
    var occ := counts[key];
    if occ > 0 then
    begin
      for var i := key + 1 to key + k - 1 do
      begin
        if (not counts.ContainsKey(i)) or (counts[i] < occ) then
        begin
          Result := False;
          exit;
        end;
        counts[i] -= occ;
      end;
    end;
  end;

  Result := True;
end;

