function CompareStringsLexicographically(str1, str2: string): integer;
begin
  var asciiStr1 := new List<integer>;
  var asciiStr2 := new List<integer>;

  foreach var ch in str1 do
    asciiStr1.Add(Ord(ch));

  foreach var ch in str2 do
    asciiStr2.Add(Ord(ch));

  var len1 := asciiStr1.Count;
  var len2 := asciiStr2.Count;

  if len1 < len2 then
    for var i := 1 to len2 - len1 do
      asciiStr1.Add(0)
  else if len1 > len2 then
    for var i := 1 to len1 - len2 do
      asciiStr2.Add(0);

  var i := 0;
  while i < asciiStr1.Count do
  begin
    if asciiStr1[i] > asciiStr2[i] then
    begin
      Result := 1;
      exit;
    end
    else if asciiStr1[i] < asciiStr2[i] then
    begin
      Result := -1;
      exit;
    end
    else
      i += 1;
  end;

  Result := 0;
end;

