function PrevPermutation(n: integer): integer;
begin
  var digits := n.ToString.ToCharArray.ToList;
  var i := digits.Count - 2;

  while (i >= 0) and (digits[i] <= digits[i + 1]) do
    i -= 1;

  if i < 0 then
  begin
    Result := -1;
    exit;
  end;

  var j := digits.Count - 1;
  while digits[j] >= digits[i] do
    j -= 1;

  var temp := digits[i];
  digits[i] := digits[j];
  digits[j] := temp;

  var rest := digits.GetRange(i + 1, digits.Count - i - 1);
  rest.Reverse;
  digits.RemoveRange(i + 1, digits.Count - i - 1);
  digits.AddRange(rest);

  Result := StrToInt(string.Join('', digits));
end;

type
  TreeNode = class
    val: integer;
    left, right: TreeNode;

