function DeepestNode(root: TreeNode): integer;

  procedure DFS(node: TreeNode; depth: integer; var deepest: (integer, integer));
  begin
    if node = nil then
      exit;

    if depth > deepest[1] then
      deepest := (node.val, depth);

    DFS(node.left, depth + 1, deepest);
    DFS(node.right, depth + 1, deepest);
  end;

begin
  var deepest := (root.val, 0);
  DFS(root, 0, deepest);
  Result := deepest[0];
end;

function MaxRectangle(matrix: array [,] of integer): integer;
begin
  if matrix.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var m := matrix.GetLength(0);
  var n := matrix.GetLength(1);
  var height := new integer[n + 1];
  var maxArea := 0;

  for var i := 0 to m - 1 do
  begin
    var stack := new Stack<integer>;
    stack.Push(-1);

    for var j := 0 to n do
    begin
      if j < n then
        height[j] := if matrix[i, j] = 1 then height[j] + 1 else 0;

      while (stack.Count > 1) and (height[j] < height[stack.Peek]) do
      begin
        var h := height[stack.Pop];
        var w := j - 1 - stack.Peek;
        maxArea := Max(maxArea, h * w);
      end;
      stack.Push(j);
    end;
  end;

  Result := maxArea;
end;

