  var n := s.Length;
  var palindromeCount := 0;

  for var center := 0 to 2 * n - 2 do
  begin
    var left := center div 2;
    var right := left + center mod 2;

    while (left >= 0) and (right < n) and (s[left + 1] = s[right + 1]) do
    begin
      palindromeCount += 1;
      left -= 1;
      right += 1;
    end;
  end;

  Result := palindromeCount;
end;

function Hamming(n: integer): integer;
begin
  var seq := new List<integer>;
  seq.Add(1);

  var ptr2 := 0;
  var ptr3 := 0;
  var ptr5 := 0;

  for var i := 1 to n - 1 do
  begin
    var next2 := 2 * seq[ptr2];
    var next3 := 3 * seq[ptr3];
    var next5 := 5 * seq[ptr5];
    var nextHamming := Min(next2, Min(next3, next5));

    seq.Add(nextHamming);

    if nextHamming = next2 then
      ptr2 += 1;
    if nextHamming = next3 then
      ptr3 += 1;
    if nextHamming = next5 then
      ptr5 += 1;
  end;

  Result := seq[n - 1];
end;

