      if grid[i, j] = 1 then
      begin
        if not rows.ContainsKey(i) then
          rows.Add(i, new HashSet<integer>);
        rows[i].Add(j);

        if not cols.ContainsKey(j) then
          cols.Add(j, new HashSet<integer>);
