function CountNQueens(n: integer): integer;

  function Backtracking(row: integer; columns: array of integer; var counts: integer): boolean;

    function Check(row, col: integer; columns: array of integer): boolean;
    begin
      for var r := 0 to row - 1 do
        if (columns[r] = col) or (row - r = Abs(columns[r] - col)) then
        begin
          Result := False;
          exit;
        end;
      Result := True;
    end;

  begin
    if row = n then
    begin
      counts += 1;
      Result := True;
      exit;
    end;

    for var col := 0 to n - 1 do
    begin
      columns[row] := col;
      if Check(row, col, columns) then
        Backtracking(row + 1, columns, counts)
      else
        columns[row] := -1;
    end;
    Result := False;
  end;

begin
  var counts := 0;
  var columns := new integer[n];
  for var i := 0 to n - 1 do
    columns[i] := -1;

  Backtracking(0, columns, counts);
  Result := counts;
end;

