      exit;
    end;

    for var i := start to chars.Length - 1 do
    begin
      var temp := chars[start];
      chars[start] := chars[i];
      chars[i] := temp;

      GeneratePermutations(chars, start + 1, res);

      temp := chars[start];
      chars[start] := chars[i];
      chars[i] := temp;
    end;
  end;

begin
  var res := new List<string>;
