function FindLargestConsecutiveRange(nums: array of integer): array of integer;
begin
  if nums.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var numSet := new HashSet<integer>(nums);
  var longestRange := new integer[2];
  var longestLength := 0;

  foreach var num in numSet do
  begin
    if not numSet.Contains(num - 1) then
    begin
      var currentLength := 1;
      var currentNum := num;

      while numSet.Contains(currentNum + 1) do
      begin
        currentNum += 1;
        currentLength += 1;
      end;

      if currentLength > longestLength then
      begin
        longestLength := currentLength;
        longestRange[0] := num;
        longestRange[1] := currentNum;
      end;
    end;
  end;

  Result := longestRange;
end;

