      Result := True;
    end;
  end;

  function Fib(k: integer): integer;
  begin
    if k <= 1 then
      Result := k
    else
    begin
      var a := 0;
      var b := 1;
      for var i := 2 to k do
      begin
        var temp := a + b;
        a := b;
        b := temp;
      end;
      Result := b;
    end;
  end;

begin
  var i := 0;
  var count := 0;
  while True do
  begin
    var fib_i := Fib(i);
    if CheckPrime(fib_i) then
    begin
      count += 1;
      if count = n then
      begin
        Result := fib_i;
        exit;
      end;
    end;
    i += 1;
  end;
end;

