function Indexes(nums: array of integer; target: integer): (integer, integer);

  function FindLeft(arr: array of integer; t: integer): integer;
  begin
    var left := 0;
    var right := arr.Length - 1;
    while left <= right do
    begin
      var mid := (left + right) div 2;
      if arr[mid] < t then
        left := mid + 1
      else
        right := mid - 1;
    end;
    if (left < arr.Length) and (arr[left] = t) then
      Result := left
    else
      Result := -1;
  end;

  function FindRight(arr: array of integer; t: integer): integer;
  begin
    var left := 0;
    var right := arr.Length - 1;
    while left <= right do
    begin
      var mid := (left + right) div 2;
      if arr[mid] <= t then
        left := mid + 1
      else
        right := mid - 1;
    end;
    if (right >= 0) and (arr[right] = t) then
      Result := right
    else
      Result := -1;
  end;

begin
  var leftIndex := FindLeft(nums, target);
  var rightIndex := FindRight(nums, target);
  Result := (leftIndex, rightIndex);
end;

