function CommonChars(words: array of string): array of char;
begin
  if words.Length = 0 then
  begin
    Result := new char[0];
    exit;
  end;

  var counter := new List<Dictionary<char, integer>>;
  foreach var word in words do
  begin
    var dict := new Dictionary<char, integer>;
    foreach var ch in word do
      if dict.ContainsKey(ch) then
        dict[ch] += 1
      else
        dict.Add(ch, 1);
    counter.Add(dict);
  end;

  var common := counter[0];
  for var i := 1 to counter.Count - 1 do
  begin
    var newCommon := new Dictionary<char, integer>;
    foreach var pair in common do
      if counter[i].ContainsKey(pair.Key) then
        newCommon.Add(pair.Key, Min(pair.Value, counter[i][pair.Key]));
    common := newCommon;
  end;

  var res := new List<char>;
  foreach var pair in common do
    for var i := 1 to pair.Value do
      res.Add(pair.Key);

  Result := res.ToArray;
end;

