function FindPermutation(s: string): integer;
begin
  var charCounts := new Dictionary<char, integer>;
  foreach var ch in s do
    if charCounts.ContainsKey(ch) then
      charCounts[ch] += 1
    else
      charCounts.Add(ch, 1);

  var denom := 1;
  foreach var count in charCounts.Values do
  begin
    var fact := 1;
    for var i := 2 to count do
      fact *= i;
    denom *= fact;
  end;

  var numerator := 1;
  for var i := 2 to s.Length do
    numerator *= i;

  Result := numerator div denom;
end;

