  for var i := 1 to sortedS.Count - 1 do
  begin
    if sortedS[i] = currentChar then
      currentCount += 1
    else
    begin
      if length = -1 then
        length := currentCount
      else if currentCount <> length then
      begin
        Result := False;
        exit;
      end;

      currentChar := sortedS[i];
      currentCount := 1;
    end;
  end;

  Result := (currentCount = length) or (length = -1);
end;

