function FindCheapestPrice(n: integer; flights: array of (integer, integer, integer); src, dst, K: integer): integer;
begin
  var dic := new Dictionary<integer, List<(integer, integer)>>;
  foreach var (s, d, p) in flights do
  begin
    if not dic.ContainsKey(s) then
      dic.Add(s, new List<(integer, integer)>);
    dic[s].Add((d, p));
  end;

  var visited := new Dictionary<integer, Dictionary<integer, integer>>;
  var h := new List<(integer, integer, integer)>;
  h.Add((0, src, 0));

  while h.Count > 0 do
  begin
    h.Sort((x, y) -> x[0].CompareTo(y[0]));
    var (time, cur, count) := h[0];
    h.RemoveAt(0);

    if cur = dst then
    begin
      Result := time;
      exit;
    end;

    if count = K + 1 then
      continue;

    if dic.ContainsKey(cur) then
    begin
      foreach var (nei, t) in dic[cur] do
      begin
        var newTime := time + t;
        var newCount := count + 1;

        if (not visited.ContainsKey(nei)) or (not visited[nei].ContainsKey(newCount)) or (visited[nei][newCount] > newTime) then
        begin
          if not visited.ContainsKey(nei) then
            visited.Add(nei, new Dictionary<integer, integer>);
          visited[nei][newCount] := newTime;
          h.Add((newTime, nei, newCount));
        end;
      end;
    end;
  end;

  Result := -1;
end;

