  var m := new Dictionary<string, TreeNode>;
  foreach var e in employees do
    m.Add(e.val, e.parent);

  var path1 := new List<string>;
  var current1 := employee1;
  while m.ContainsKey(current1) and (m[current1] <> nil) do
  begin
    path1.Add(current1);
    current1 := m[current1].val;
  end;
  path1.Add(current1);

  var path2 := new List<string>;
  var current2 := employee2;
  while m.ContainsKey(current2) and (m[current2] <> nil) do
  begin
    path2.Add(current2);
    current2 := m[current2].val;
  end;
  path2.Add(current2);

  path1.Reverse;
  path2.Reverse;

  var prev := '';
  for var i := 0 to Min(path1.Count, path2.Count) - 1 do
  begin
    if path1[i] <> path2[i] then
      break;
    prev := path1[i];
  end;

  Result := prev;
end;

