function HasCycle(edges: array of (integer, integer)): boolean;

  function DFS(node: integer; visited: HashSet<integer>; recursionStack: HashSet<integer>; adjacencyList: Dictionary<integer, List<integer>>): boolean;
  begin
    visited.Add(node);
    recursionStack.Add(node);

    if adjacencyList.ContainsKey(node) then
    begin
      foreach var neighbor in adjacencyList[node] do
      begin
        if not visited.Contains(neighbor) then
        begin
          if DFS(neighbor, visited, recursionStack, adjacencyList) then
          begin
            Result := True;
            exit;
          end;
        end
        else if recursionStack.Contains(neighbor) then
        begin
          Result := True;
          exit;
        end;
      end;
    end;

    recursionStack.Remove(node);
    Result := False;
  end;

begin
  var nodes := new HashSet<integer>;
  foreach var edge in edges do
  begin
    nodes.Add(edge[0]);
    nodes.Add(edge[1]);
  end;

  var adjacencyList := new Dictionary<integer, List<integer>>;
  foreach var node in nodes do
    adjacencyList.Add(node, new List<integer>);

  foreach var (src, dest) in edges do
    adjacencyList[src].Add(dest);

  var visited := new HashSet<integer>;
  foreach var node in nodes do
  begin
    if not visited.Contains(node) then
    begin
      var recursionStack := new HashSet<integer>;
      if DFS(node, visited, recursionStack, adjacencyList) then
      begin
        Result := True;
        exit;
      end;
    end;
  end;

  Result := False;
end;

