function SortSentence(s: string): string;
begin
  var temp := s.Split(' ').ToList;
  var index := new List<integer>;
  var count := 0;
  var answer := '';

  for var i := 0 to temp.Count - 1 do
  begin
    var ele := temp[i];
    index.Add(StrToInt(ele[ele.Length]));
    temp[i] := ele.Substring(0, ele.Length - 1);
    count += 1;
  end;

  var dec := new Dictionary<integer, string>;
  for var i := 0 to temp.Count - 1 do
    dec.Add(index[i], temp[i]);

  for var i := 0 to index.Count - 1 do
  begin
    var least := i;
    for var k := i + 1 to index.Count - 1 do
      if index[k] < index[least] then
        least := k;

    var tempIndex := index[i];
    index[i] := index[least];
    index[least] := tempIndex;
  end;

  foreach var ele in index do
    answer += dec[ele] + ' ';

  Result := answer.Trim;
end;

