    xorResult := xorResult and (xorResult - 1);
  end;
  Result := distance;
end;

function DecodeMessage(s: string): integer;
begin
  var dp := new integer[s.Length + 1];
  dp[0] := 1;
  dp[1] := if (s.Length > 0) and (StrToInt(s[1]) > 0) and (StrToInt(s[1]) <= 9) then 1 else 0;

  for var i := 2 to s.Length do
  begin
    var oneDigit := StrToInt(s[i]);
    var twoDigit := StrToInt(s.Substring(i - 1, 2));

    if (oneDigit > 0) and (oneDigit <= 9) then
      dp[i] += dp[i - 1];

    if (twoDigit >= 10) and (twoDigit <= 26) then
      dp[i] += dp[i - 2];
  end;

  Result := dp[s.Length];
end;

function FindMinJumps(arr: array of integer): integer;
begin
  var n := arr.Length;
  if n <= 1 then
  begin
    Result := 0;
    exit;
  end;

  if arr[0] = 0 then
  begin
    Result := integer.MaxValue;
    exit;
  end;

  var maxReach := arr[0];
  var step := arr[0];
  var jump := 1;

  for var i := 1 to n - 1 do
  begin
    if i = n - 1 then
    begin
      Result := jump;
      exit;
    end;

    maxReach := Max(maxReach, i + arr[i]);
    step -= 1;

    if step = 0 then
    begin
      jump += 1;
      if i >= maxReach then
      begin
        Result := integer.MaxValue;
        exit;
      end;
      step := maxReach - i;
    end;
  end;

  Result := jump;
end;

