  else if n = 2 then
    Result := 2
  else if n = 3 then
    Result := 4
  else
  begin
    var dp := new integer[n + 1];
    dp[0] := 1;
    dp[1] := 1;
    dp[2] := 2;
    dp[3] := 4;

    for var i := 4 to n do
      dp[i] := dp[i - 1] + dp[i - 3] + dp[i - 4];

    Result := dp[n];
  end;
end;

function FindDayOfYear(year, month, day: integer): integer;
begin
  var date := System.DateTime.Create(year, month, day);
  Result := date.DayOfYear;
end;

function IsAlphanumeric(s: string): boolean;
begin
  foreach var ch in s do
    if not char.IsLetterOrDigit(ch) then
      exit(false);
  Result := True;
end;

function IsFibonacci(n: integer): boolean;
begin
  if (n = 0) or (n = 1) then
  begin
    Result := True;
    exit;
  end;

  var a := 0;
  var b := 1;
  while b < n do
  begin
    var temp := a + b;
    a := b;
    b := temp;
  end;
  Result := b = n;
end;

function WaysToReachStair(n: integer): integer;
begin
  if n <= 1 then
    Result := n
  else
  begin
    var first := 0;
    var second := 1;
    for var i := 0 to n - 1 do
    begin
      var currentStep := first + second;
      first := second;
      second := currentStep;
    end;
    Result := second;
  end;
end;

function CountGoodNumbers(n: integer): integer;

  function IsGoodNumber(num: integer): boolean;
  begin
    var rotateMap := new Dictionary<char, char>;
    rotateMap.Add('0', '0');
    rotateMap.Add('1', '1');
    rotateMap.Add('8', '8');
    rotateMap.Add('2', '5');
    rotateMap.Add('5', '2');
    rotateMap.Add('6', '9');
    rotateMap.Add('9', '6');

    var original := num.ToString;
    var rotated := '';

    foreach var digit in original do
    begin
      if not rotateMap.ContainsKey(digit) then
      begin
        Result := False;
        exit;
      end;
      rotated += rotateMap[digit];
    end;

    Result := original <> rotated;
  end;

begin
  var count := 0;
  for var i := 1 to n do
    if IsGoodNumber(i) then
      count += 1;
  Result := count;
end;

